def minCosts(cost: List[int]) -> List[int]:
    n = len(cost)
    answer = [0] * n

    for i in range(n):
        answer[i] = cost[i] if i == 0 else min(answer[i - 1], cost[i])
        # Update the current cost considering that we can swap with any
        # previous person for free after paying to the one directly in front.
        if i > 0:
            answer[i] = min(answer[i], cost[i])
            if i > 1:
                answer[i] = min(answer[i], answer[i-1])

    return answer

