def longestSubsequence(nums: List[int]) -> int:
    n = len(nums)
    if n == 0:
        return 0
    dp = [1] * n
    for i in range(n):
        for j in range(i):
            if abs(nums[i] - nums[j]) >= (abs(nums[j] - nums[j-1]) if j > 0 else float('inf')):
                dp[i] = max(dp[i], dp[j] + 1)
            else:
                dp[i] = max(dp[i], dp[j])
    return max(dp)

def calculateScore(s: str) -> int:
    score = 0
    n = len(s)
    marked = [False] * n
    mirror = {chr(i): chr(219 - i) for i in range(97, 123)}  # 'a' to 'z' mirrors

    for i in range(n):
        if marked[i]:
            continue
        mirror_char = mirror[s[i]]
        for j in range(i - 1, -1, -1):
            if not marked[j] and s[j] == mirror_char:
                marked[i] = True
                marked[j] = True
                score += i - j
                break

    return score

