from collections import defaultdict, deque


def minMaxWeight(n: int, edges: List[List[int]], threshold: int) -> int:
    # Function to check if we can reach node 0 with a given max weight
    def canReachWithMaxWeight(max_weight: int) -> bool:
        graph = defaultdict(list)
        for u, v, w in edges:
            if w <= max_weight:
                graph[v].append(u)  # Reverse direction to find paths to node 0

        # BFS to check reachability from all nodes to node 0
        queue = deque([0])
        visited = set([0])
        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

        return len(visited) == n  # Check if all nodes can reach node 0

    # Binary search over the possible maximum edge weights
    low, high = 1, 10**6
    result = -1
    while low <= high:
        mid = (low + high) // 2
        # Check if we can reach all nodes using edges with weight <= mid
        if canReachWithMaxWeight(mid):
            result = mid
            high = mid - 1  # Try to find a smaller max weight
        else:
            low = mid + 1  # Increase the weight

    # After finding the minimum max weight, check if it satisfies the threshold condition
    if result != -1:
        out_degree = [0] * n
        for u, v, w in edges:
            if w <= result:
                out_degree[u] += 1

        # Check if we exceed the threshold
        if any(out > threshold for out in out_degree):
            return -1

    return result

