def minCost(n: int, cost: List[List[int]]) -> int:
    # Dynamic programming table to store minimum costs
    dp = [[0] * 3 for _ in range(n)]
    # Initialize the first house with the costs of painting it with each color
    dp[0] = cost[0]

    # Fill the dp table for all houses
    for i in range(1, n):
        for j in range(3):
            dp[i][j] = cost[i][j] + min(
                dp[i - 1][(j + 1) % 3],
                dp[i - 1][(j + 2) % 3]
            )
            if i < n // 2:
                dp[i][j] += (dp[n - 1 - i][j] if i > 0 else float('inf'))

    # The minimum cost considering equidistant constraints
    min_cost = float('inf')
    for j in range(3):
        min_cost = min(min_cost, dp[n//2 - 1][j] + dp[n - 1][(j + 1) % 3], dp[n - 1][(j + 2) % 3])

    return min_cost

from typing import List

def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    online_status = [True] * numberOfUsers
    offline_until = [0] * numberOfUsers

    for event in events:
        event_type, timestamp, *args = event
        timestamp = int(timestamp)

        # Update online status before processing messages
        for user_id in range(numberOfUsers):
            if not online_status[user_id] and timestamp >= offline_until[user_id]:
                online_status[user_id] = True

        if event_type == "OFFLINE":
            if args:
                user_id = int(args[0][2:])  # Extracting id
                online_status[user_id] = False
                offline_until[user_id] = timestamp + 60

        elif event_type == "MESSAGE":
            mentions_string = args[0]
            if mentions_string == "ALL":
                for i in range(numberOfUsers):
                    mentions[i] += 1
            elif mentions_string == "HERE":
                for i, is_online in enumerate(online_status):
                    if is_online:
                        mentions[i] += 1
            else:
                mentioned_ids = mentions_string.split()
                for mention in mentioned_ids:
                    user_id = int(mention[2:])  # Extracting id
                    mentions[user_id] += 1

    return mentions

from typing import List

def maxFreeTime(eventTime: int, k: int, startTime: List[int], endTime: List[int]) -> int:
    n = len(startTime)
    free_times = []

    # Calculate initial free times between meetings
    if startTime[0] > 0:
        free_times.append(startTime[0])  # Free time before the first meeting
    for i in range(1, n):
        free_times.append(max(0, startTime[i] - endTime[i - 1]))  # Free time between meetings
    if endTime[-1] <= eventTime:
        free_times.append(eventTime - endTime[-1])  # Free time after the last meeting

    # Sort free times in descending order
    free_times.sort(reverse=True)

    # If k is greater than or equal to the number of free periods, return the largest free period
    if k >= len(free_times):
        return free_times[0] if free_times else 0

    # We can reschedule k meetings, so we take the k largest free times
    return sum(free_times[:k])

def maxDistance(s: str, k: int) -> int:
    # Initial position
    x, y = 0, 0
    # Count movements
    for char in s:
        if char == 'N':
            y += 1
        elif char == 'S':
            y -= 1
        elif char == 'E':
            x += 1
        elif char == 'W':
            x -= 1
    # Current Manhattan distance
    current_distance = abs(x) + abs(y)
    # Add the adjustment for maximum distance possible with k changes
    max_distance = current_distance + k
    return max_distance
